head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst01401";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — etfOvrvw, etfProdInfo, etfIdxMktInfo

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst01401.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "a_95", attr: "src", fn: function () { return String(dma_etfProdInfo.get("hpage")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_17_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_18", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_22_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_23", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_28_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_29", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_33_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_34", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_39_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_40", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_44_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_45", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_50_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_51", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_55_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_56", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_61_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_62", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_66_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_67", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_72_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_73", fn: function(){ return (!((!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)))); } }, { id: "c_when_77_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_78", fn: function(){ return (!((!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)))); } }, { id: "c_when_83_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_84", fn: function(){ return (!((!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_88_txt", fn: function(){ return (!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_89", fn: function(){ return (!((!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)))); } }, { id: "a_95", fn: function(){ return (!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_96", fn: function(){ return (!((!(String(((dma_pageContext.get("etfProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfProdInfo") ?? ""))).length === 0)))); } }, { id: "if_etfOvrvw", fn: function(){ return (!(String(((dma_pageContext.get("etfOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etfOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_113", fn: function(){ return (!((!(String(((dma_etfIdxMktInfo.get("mktUpclss") ?? (() => { throw new Error("unresolved:" + "etfIdxMktInfo.mktUpclss"); })())) == null ? '' : ((dma_etfIdxMktInfo.get("mktUpclss") ?? (() => { throw new Error("unresolved:" + "etfIdxMktInfo.mktUpclss"); })()))).length === 0)))); } }, { id: "c_otherwise_118", fn: function(){ return (!((!(String(((dma_etfIdxAsstInfo.get("asstUpclss") ?? (() => { throw new Error("unresolved:" + "etfIdxAsstInfo.asstUpclss"); })())) == null ? '' : ((dma_etfIdxAsstInfo.get("asstUpclss") ?? (() => { throw new Error("unresolved:" + "etfIdxAsstInfo.asstUpclss"); })()))).length === 0)))); } }, { id: "if_etfIdxMktInfo", fn: function(){ return (!(String(((dma_pageContext.get("etfIdxMktInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etfIdxMktInfo") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "a_95", fn: function () { return String(dma_etfProdInfo.get("hpage")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
